import{Z as e,e as a,f as i,a0 as t}from"./chunks/framework.DmpHOl9T.js";const k=JSON.parse('{"title":"Cached Forms in Production","description":"","frontmatter":{},"headers":[],"relativePath":"guides/frontend-headless/cached-forms-in-production.md","filePath":"guides/frontend-headless/cached-forms-in-production.md","lastUpdated":1782532814000}'),n={name:"guides/frontend-headless/cached-forms-in-production.md"};function r(o,s,l,h,p,d){return a(),i("div",null,[...s[0]||(s[0]=[t(`<h1 id="cached-forms-in-production" tabindex="-1">Cached Forms in Production <a class="header-anchor" href="#cached-forms-in-production" aria-label="Permalink to &quot;Cached Forms in Production&quot;">​</a></h1><p>Statically cached pages can serve form HTML with stale CSRF tokens, request tokens, and render IDs — which produces random-looking submit failures. Formie refreshes those values automatically when static-cache support is enabled. This guide covers production setups for Twig-rendered forms, Blitz, Craft Cloud, and headless React/Vue apps.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li><a href="/frontend/cached-forms">Cached Forms</a> reference</li><li><a href="/get-started/configuration">Configuration</a> — <code>staticCacheRefreshOnLoad</code> and related settings</li></ul><h2 id="why-cached-forms-fail-without-refresh" tabindex="-1">Why Cached Forms Fail Without Refresh <a class="header-anchor" href="#why-cached-forms-fail-without-refresh" aria-label="Permalink to &quot;Why Cached Forms Fail Without Refresh&quot;">​</a></h2><p>When a page is served from full-page cache, the HTML may be minutes or hours old. Form submissions depend on request-specific values:</p><ul><li>Craft CSRF token</li><li>Formie <code>requestToken</code> (duplicate-submit and replay protection)</li><li>Formie <code>renderId</code> (form instance identity)</li></ul><p>If any of these are stale, submissions fail in ways that look intermittent — especially on first load after cache warm, or after a user leaves the tab open.</p><h2 id="enable-automatic-refresh" tabindex="-1">Enable Automatic Refresh <a class="header-anchor" href="#enable-automatic-refresh" aria-label="Permalink to &quot;Enable Automatic Refresh&quot;">​</a></h2><p>Formie marks forms as cache-aware and refreshes tokens on initialisation, then again after submit attempts.</p><p><strong>Blitz</strong> — refresh is enabled automatically when Blitz is installed and enabled. No extra config required.</p><p><strong>Other static caches</strong> — enable the plugin setting:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;*&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &#39;staticCacheRefreshOnLoad&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>In most Twig setups, that is all you need. Formie calls the refresh endpoint on load and patches the existing form DOM.</p><h2 id="craft-cloud-and-async-csrf" tabindex="-1">Craft Cloud and Async CSRF <a class="header-anchor" href="#craft-cloud-and-async-csrf" aria-label="Permalink to &quot;Craft Cloud and Async CSRF&quot;">​</a></h2><p>On Craft Cloud and other full-page caches, a synchronous CSRF token in the rendered HTML can prevent the page from being cache-eligible — even if Formie would refresh tokens later.</p><p>Enable async CSRF globally:</p><div class="language-php vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">php</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &#39;asyncCsrfInputs&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span></code></pre></div><p>Or via environment: <code>CRAFT_ASYNC_CSRF_INPUTS=true</code>.</p><p>Formie uses Craft&#39;s <code>csrfInput()</code> helper, so the global setting applies automatically.</p><h3 id="per-form-render-options" tabindex="-1">Per-Form Render Options <a class="header-anchor" href="#per-form-render-options" aria-label="Permalink to &quot;Per-Form Render Options&quot;">​</a></h3><p>When you need per-form control instead of a global async CSRF setting:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    csrfInput: { async: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> },</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Or omit the CSRF input entirely and let Formie inject it during token refresh:</p><div class="language-twig vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">twig</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{{ craft.formie.renderForm(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;contactForm&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    csrfInput: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}) }}</span></span></code></pre></div><p>Use <code>csrfInput: false</code> only when static-cache token refresh is enabled. Formie creates the hidden input on refresh if one is not already present.</p><h2 id="what-refresh-returns" tabindex="-1">What Refresh Returns <a class="header-anchor" href="#what-refresh-returns" aria-label="Permalink to &quot;What Refresh Returns&quot;">​</a></h2><p>The refresh payload looks like this:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;csrf&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;param&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;CRAFT_CSRF_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;token&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;3YV0bKqQx...&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;requestToken&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;m1f8A2pQ...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;renderId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;formie-contact-form-abc123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Formie applies those values back onto the existing form. The cached HTML keeps working without a full re-render.</p><h2 id="headless-and-byo-bundle-setups" tabindex="-1">Headless and BYO Bundle Setups <a class="header-anchor" href="#headless-and-byo-bundle-setups" aria-label="Permalink to &quot;Headless and BYO Bundle Setups&quot;">​</a></h2><p>When you mount forms through <code>@verbb/formie-react</code>, <code>@verbb/formie-vue</code>, or <code>@verbb/formie-browser</code> directly, pass static-cache options at mount time:</p><div class="language-tsx vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">tsx</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">FormieForm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    transport</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;rest&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    endpoint</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://your-craft-site.test&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    formHandle</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;contactForm&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    staticCache</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    refreshTokens</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/&gt;</span></span></code></pre></div><p>If you take over Formie&#39;s browser assets entirely (manual bundle, custom mount), keep token refresh enabled in your mount options. Disabling refresh on a statically cached page will reproduce the stale-token failures.</p><p>GraphQL headless apps bootstrap via <code>formieClientForm</code> and refresh via <code>refreshFormieClientSession</code>. The front-end packages call these automatically when <code>refreshTokens</code> is true.</p><h2 id="rate-limits-on-anonymous-refresh" tabindex="-1">Rate Limits on Anonymous Refresh <a class="header-anchor" href="#rate-limits-on-anonymous-refresh" aria-label="Permalink to &quot;Rate Limits on Anonymous Refresh&quot;">​</a></h2><p>Formie rate-limits anonymous bootstrap and token-refresh requests to protect against abuse:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th></tr></thead><tbody><tr><td><code>anonymousClientBootstrapRateLimit</code></td><td>30 per window</td></tr><tr><td><code>anonymousClientRefreshRateLimit</code></td><td>120 per window</td></tr><tr><td><code>anonymousClientRateWindowSeconds</code></td><td>60</td></tr></tbody></table><p>Set a limit to <code>0</code> to disable it. High-traffic cached pages rarely hit these limits because refresh runs once per form mount, not per page view — but load tests on a single IP can.</p><h2 id="production-checklist" tabindex="-1">Production Checklist <a class="header-anchor" href="#production-checklist" aria-label="Permalink to &quot;Production Checklist&quot;">​</a></h2><ol><li><strong>Identify your cache layer</strong> — Blitz, Craft Cloud, CDN, or custom static HTML.</li><li><strong>Enable refresh</strong> — auto for Blitz; <code>staticCacheRefreshOnLoad</code> otherwise.</li><li><strong>Fix CSRF cache eligibility</strong> — <code>asyncCsrfInputs</code> or <code>csrfInput: false</code> on Craft Cloud.</li><li><strong>Verify in browser</strong> — load a cached page, inspect network for the refresh request, submit the form.</li><li><strong>Headless apps</strong> — pass <code>staticCache</code> and <code>refreshTokens</code> to framework components.</li><li><strong>After deploy</strong> — confirm captchas and payment fields still initialise post-refresh (they receive updated module config in the session payload).</li></ol><h2 id="when-refresh-is-not-enough" tabindex="-1">When Refresh Is Not Enough <a class="header-anchor" href="#when-refresh-is-not-enough" aria-label="Permalink to &quot;When Refresh Is Not Enough&quot;">​</a></h2><p>If you customise save/resume, multi-page Ajax, or SPA navigation (Barba, Sprig, Datastar), you may need to re-mount Formie when the form DOM is replaced. The starters include examples:</p><ul><li><a href="https://formie-starters.verbb.io/barba" target="_blank" rel="noreferrer">Barba.js example</a></li><li><a href="https://formie-starters.verbb.io/sprig" target="_blank" rel="noreferrer">Sprig example</a></li><li><a href="https://formie-starters.verbb.io/datastar" target="_blank" rel="noreferrer">Datastar example</a></li></ul><p>The pattern is the same: unmount the old instance, mount fresh on the new DOM, and let refresh run on the new mount.</p>`,45)])])}const u=e(n,[["render",r]]);export{k as __pageData,u as default};
